def build_tool_list(allow_write: bool):
    tools = [LIST_DIRECTORY, READ_FILE]
    if allow_write:
        tools += [WRITE_FILE, DELETE_FILE]
    return tools

MAX_READ_BYTES = 200_000

def read_file_safely(path: str) -> str:
    size = os.path.getsize(path)
    if size > MAX_READ_BYTES:
        raise ValueError(f"file too large to read ({size} bytes), use a narrower query")
    with open(path, "r", encoding="utf-8", errors="strict") as f:
        return f.read()

def list_directory(rel_path: str):
    target = resolve_scoped_path(rel_path)
    entries = []
    for name in sorted(os.listdir(target)):
        full = os.path.join(target, name)
        entries.append({
            "name": name,
            "type": "directory" if os.path.isdir(full) else "file",
            "size": None if os.path.isdir(full) else os.path.getsize(full),
        })
    return entries

def audit_log(session_id, tool_name, resolved_path, outcome):
